head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > dragStartFunction]<br/>Drag 된 데이터가 GridView 에 Drop 되었을때 호출할 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "Drag&Drop 관련 이벤트는 ondatadragstart > ondatadragover > [dragStartFunction] > [ondatadrop|dragEndFunction] 순서로 발생합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (이벤트 발생 순서 전용)
//  - 좌 target1(Drag 소스) : dataDragDropOther=true + dragStartFunction 정의
//  - 우 target2(Drop 대상) : dataDragDropOther=true + dragEndFunction 정의
//  - 발생 순서 : ondatadragstart(좌) > ondatadragover(우) > dragStartFunction(좌) > [ondatadrop(우) 대신 dragEndFunction(우)]
//    (dragEndFunction 정의 시 엔진은 ondatadrop 대신 dragEndFunction 호출 -> eventController.js:1248/1365 분기)
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제 (2개 그리드 + 2개 dataList)
    if (typeof dlt_bind1 !== 'undefined') {
        $p.data.remove("dlt_bind1");
    }
    if (typeof dlt_bind2 !== 'undefined') {
        $p.data.remove("dlt_bind2");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof target2 !== 'undefined') {
        target2.remove();
    }
    // 이전에 만든 flex wrapper 도 제거 (Target 재생성 시 중복 누적 방지)
    if (scwin.gridFlexWrap && scwin.gridFlexWrap.parentNode) {
        scwin.gridFlexWrap.parentNode.removeChild(scwin.gridFlexWrap);
    }

    // 안내 라벨 (가장 먼저 생성)
    //  - 발생 위치(좌/우)와 ondatadrop 대신 dragEndFunction 호출 전제를 안내
    $c.gcm.createLabel('label="[전제] 왼쪽 target1=Drag 소스, 오른쪽 target2=Drop 대상.\n[절차] target1 행을 target2 로 드래그하면 Drag&Drop 관련 이벤트가 순서대로 발생합니다."', '', 'label1');

    // 좌우 배치용 flex wrapper 와 좌/우 셀(원시 DOM div) 생성
    let grpBasic = document.querySelector('.tc_group_basic');
    scwin.gridFlexWrap = document.createElement('div');
    scwin.gridFlexWrap.style.cssText = 'display:flex; gap:20px; align-items:flex-start;';
    let cellLeft = document.createElement('div');
    let cellRight = document.createElement('div');
    scwin.gridFlexWrap.appendChild(cellLeft);
    scwin.gridFlexWrap.appendChild(cellRight);
    grpBasic.appendChild(scwin.gridFlexWrap);

    // target1(소스) : dataDragDropOther=true + dragStartFunction 정의
    //  - dataDragDrop=true 병행 : 실제 마우스 Drag&Drop 시 엔진 onDrop 비-drilldown 분기(eventController.js)에서
    //    dragEndFunction 호출 경로(~1358 dataDragDrop 분기)를 활성화. dataDragDropOther 단독으로는 dragStartFunction 만
    //    호출되고 dragEndFunction 이 호출되지 않아 실제 행 이동이 일어나지 않음. (자기자신 Drop 차단은 Other 가 담당)
    let properties1 = {
        dataList: "data:dlt_bind1",
        dataDragDrop: "true",
        dataDragDropOther: "true",
        dragStartFunction: "scwin.target1_dragStartFunc"
    };
    // target2(Drop 대상) : dataDragDropOther=true + dragEndFunction 정의
    let properties2 = {
        dataList: "data:dlt_bind2",
        dataDragDropOther: "true",
        dragEndFunction: "scwin.target2_dragEndFunc"
    };

    let cList1 = $c.gcm.createCList(properties1);
    let cList2 = $c.gcm.createCList(properties2);

    // ondatadragover 발생 횟수 카운터 초기화 (연속 발생 -> 3회까지만 출력)
    scwin.overCnt = 0;

    // 이벤트 핸들러 부착 (전체 발생 순서 체인 확인용)
    //  - target1(소스) : ondatadragstart
    //  - target2(Drop 대상) : ondatadragover + ondatadrop (ondatadrop 은 dragEndFunction 정의 시 미발생)
    let eList1 = $c.gcm.createEList(["ondatadragstart"], "target1");
    let eList2 = $c.gcm.createEList(["ondatadragover", "ondatadrop"], "target2");

    // dataList 2개 생성 (각 그리드 바인딩)
    $c.gcm.createBasicDataList('', '', 'dlt_bind1');
    $c.gcm.createBasicDataList('', '', 'dlt_bind2');

    // target 2개 생성 (target1 : Drag 소스 = 왼쪽 / target2 : Drop 대상 = 오른쪽)
    await $c.gcm.createBasicGridView(cList1, eList1, 'target1', cellLeft);
    await $c.gcm.createBasicGridView(cList2, eList2, 'target2', cellRight);

    // Drop 대상(target2)은 빈 상태로 시작 -> 이동이 눈에 보이게 (target1 은 createBasicDataList 기본 4행 유지)
    dlt_bind2.setJSON([], false);
}



// 1단계 ondatadragstart : Drag 가 시작된 GridView(target1=좌)에서 발생
scwin.target1_ondatadragstart = function (rowIndex) {
    scwin.overCnt = 0;
    var bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("▶ 1. ondatadragstart 발생 (발생 GridView : target1=좌, rowIndex=" + rowIndex + ")");
};



// 2단계 ondatadragover : Drag 시작 GridView(좌)에선 미발생, 다른 GridView(target2=우)로 이동 시 발생 (연속 발생 -> 3회까지만 출력)
scwin.target2_ondatadragover = function (fromId, fromRowIndex) {
    var bottom = wf_body_bottom.getObj("scwin");
    if (scwin.overCnt < 3) {
        bottom.setReturnValue("▶ 2. ondatadragover 발생 (발생 GridView : target2=우, fromRowIndex=" + fromRowIndex + ")");
        if (scwin.overCnt === 2) {
            bottom.setReturnValue("... (이후 ondatadragover 출력 생략)");
        }
    }
    scwin.overCnt += 1;
};



// 3단계 dragStartFunction : Drag 가 시작된 GridView(target1=좌)에 정의된 사용자 정의 함수 -> Drop 시점에 호출 (ondatadrop/dragEndFunction 보다 먼저)
//  - this : Drag 가 시작된 GridView(target1=좌)
//  - XML 객체(rowXml) 반환 -> target2 의 dragEndFunction 두번째 인자로 전달
scwin.target1_dragStartFunc = function (rowIndex, rowXml, info) {
    var bottom = wf_body_bottom.getObj("scwin");
    var thisId = (this && this.id) ? this.id : "";
    bottom.setReturnValue("▶ 3. dragStartFunction 호출 (정의 위치 GridView : " + thisId + "=좌, rowIndex=" + rowIndex + ")");
    return rowXml;
};



// ondatadrop : Drop 된 GridView(target2=우)에서 발생 -> 단, dragEndFunction 이 정의되어 있으면 엔진이 ondatadrop 대신 dragEndFunction 을 호출(미발생)
scwin.target2_ondatadrop = function (info) {
    var bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("▶ (대체됨) ondatadrop 발생 (발생 GridView : target2=우) - dragEndFunction 정의 시 미발생");
};



// 4단계 dragEndFunction : Drop 된 GridView(target2=우)에 정의 -> ondatadrop 대신 호출 (체인의 마지막 단계)
scwin.target2_dragEndFunc = function (toRowIndex, rowXml, info) {
    var bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("▶ 4. dragEndFunction 호출 (정의 위치 GridView : target2=우, ondatadrop 대신 호출, toRowIndex=" + toRowIndex + ")");

    // Drop 처리 직접 구현 : 전달받은 rowXml 을 Drop 대상(target2)에 실제 행으로 삽입 (toRowIndex 초과 시 말미)
    var isXmlObj = !!(rowXml && rowXml.nodeType && rowXml.nodeName);
    if (isXmlObj) {
        var insertIdx = toRowIndex;
        var cnt = target2.getRowCount();
        if (typeof insertIdx !== "number" || insertIdx < 0 || insertIdx > cnt) {
            insertIdx = cnt;
        }
        target2.dataList.setRowXML(insertIdx, rowXml);
        bottom.setReturnValue("실제 Drop 처리(행 이동) 완료 : target2 의 " + insertIdx + " 위치에 행 삽입 (현재 target2 행 수=" + target2.getRowCount() + ")");
    }

    // true 반환 시 엔진이 Drag 소스(target1)의 원본 Row 를 자동 제거(eventController.js:1360 removeRow) -> 이동 완성
    return true;
};
